1	package credit
2	
3	import (
4		"path/filepath"
5		"strings"
6		"testing"
7	)
8	
9	// 免修编号只在所属学生名下唯一：本组用例为两名学生共享要求编号 r1 与
10	// 免修编号 w1 的情形提供可重复执行的回归检查，覆盖申请归属、有效状态、
11	// 学分来源与免修历史的隔离，以及同一学生名下既有冲突规则不受影响。
12	
13	// sharedWaiverOwner 描述一名参与“同号要求 + 同号免修”情形的学生。
14	type sharedWaiverOwner struct {
15		student string
16		course  string
17		name    string
18		credit  int
19		basis   string
20	}
21	
22	func sharedWaiverOwners() []sharedWaiverOwner {
23		return []sharedWaiverOwner{
24			{"s1", "c1", "高等数学", 4, "学科竞赛获奖"},
25			{"s2", "c2", "线性代数", 3, "外校修读证明"},
26		}
27	}
28	
29	// setupSharedWaivers 按 registerOrder 的顺序登记两名学生：各自有一项编号为
30	// r1 的要求，分别指向 4 学分和 3 学分的课程，两人都没有任何修读。
31	func setupSharedWaivers(t *testing.T, s *Store, registerOrder []sharedWaiverOwner) {
32		t.Helper()
33		for _, o := range sharedWaiverOwners() {
34			mustCourse(t, s, o.course, o.name, o.credit)
35		}
36		for _, o := range registerOrder {
37			mustStudent(t, s, o.student)
38		}
39		for _, o := range registerOrder {
40			mustReq(t, s, o.student, "r1", o.course)
41		}
42		// 两人初始都没有通过修读：0 学分、要求未满足、没有任何免修历史。
43		for _, o := range registerOrder {
44			assertWaiverOwnerUnmet(t, s, o.student, o)
45		}
46	}
47	
48	// assertWaiverOwnerUnmet 核对该学生尚未因同号免修获得任何东西：
49	// 0 学分、r1 未满足且无来源，免修历史中没有任何人的申请。
50	func assertWaiverOwnerUnmet(t *testing.T, s *Store, student string, o sharedWaiverOwner) {
51		t.Helper()
52		rep := s.CheckStudent(student)
53		if rep.TotalCredits != 0 {
54			t.Fatalf("学生 %s 在申请前总学分应为 0，得到 %d", student, rep.TotalCredits)
55		}
56		if len(rep.Unmet) != 1 || rep.Unmet[0] != "r1" {
57			t.Fatalf("学生 %s 的要求 r1 应未满足，得到 %v", student, rep.Unmet)
58		}
59		if len(rep.Requirements) != 1 {
60			t.Fatalf("学生 %s 应只有一项要求 r1，得到 %d 项", student, len(rep.Requirements))
61		}
62		st := rep.Requirements[0]
63		if st.Satisfied || st.Source != "" || st.WaiverID != "" {
64			t.Fatalf("学生 %s 的要求不应有免修来源，得到 %+v", student, st)
65		}
66		if st.Course == nil || st.Course.ID != o.course || st.Course.Credit != o.credit {
67			t.Fatalf("学生 %s 的 r1 应指向本人课程 %s（%d 学分），得到 %+v",
68				student, o.course, o.credit, st.Course)
69		}
70		if w := s.Waiver(student, "w1"); w != nil {
71			t.Fatalf("学生 %s 名下在申请前不应存在免修 w1，得到 %+v", student, w)
72		}
73		if ws := s.Waivers(student); len(ws) != 0 {
74			t.Fatalf("学生 %s 的免修历史应为空，得到 %+v", student, ws)
75		}
76		if len(rep.RejectedWaivers) != 0 || len(rep.RevokedWaivers) != 0 {
77			t.Fatalf("学生 %s 不应有被拒绝或已撤销的免修，得到 %+v / %v",
78				student, rep.RejectedWaivers, rep.RevokedWaivers)
79		}
80	}
81	
82	// assertWaiverOwnerSatisfied 核对该学生的 r1 由本人名下的 w1 满足：
83	// 学分是本人课程的学分、来源指向本人的 w1、免修历史只保留本人依据。
84	func assertWaiverOwnerSatisfied(t *testing.T, s *Store, student string, o sharedWaiverOwner) {
85		t.Helper()
86		rep := s.CheckStudent(student)
87		if rep.TotalCredits != o.credit {
88			t.Fatalf("学生 %s 应只有本人课程的 %d 学分，得到 %d",
89				student, o.credit, rep.TotalCredits)
90		}
91		if len(rep.Unmet) != 0 {
92			t.Fatalf("学生 %s 的要求应已满足，未满足=%v", student, rep.Unmet)
93		}
94		st := rep.Requirements[0]
95		if !st.Satisfied || st.Source != "waiver" || st.WaiverID != "w1" {
96			t.Fatalf("学生 %s 的要求应由本人的有效免修 w1 满足，得到 %+v", student, st)
97		}
98		if st.Course == nil || st.Course.ID != o.course || st.Course.Credit != o.credit {
99			t.Fatalf("学生 %s 的学分来源应是本人课程 %s《%s》%d 学分，得到 %+v",
100				student, o.course, o.name, o.credit, st.Course)
101		}
102		if len(rep.RejectedWaivers) != 0 || len(rep.RevokedWaivers) != 0 {
103			t.Fatalf("学生 %s 不应有被拒绝或已撤销的免修，得到 %+v / %v",
104				student, rep.RejectedWaivers, rep.RevokedWaivers)
105		}
106		w := s.Waiver(student, "w1")
107		if w == nil {
108			t.Fatalf("学生 %s 名下应存在免修 w1", student)
109		}
110		if w.StudentID != student || w.ReqID != "r1" || w.Basis != o.basis ||
111			w.Status != WaiverApproved {
112			t.Fatalf("学生 %s 的 w1 应是本人 r1 的有效免修、依据 %q，得到 %+v",
113				student, o.basis, w)
114		}
115		ws := s.Waivers(student)
116		if len(ws) != 1 || ws[0] != w {
117			t.Fatalf("学生 %s 的免修历史应只有本人的 w1 一条，得到 %+v", student, ws)
118		}
119	}
120	
121	// runSharedWaiverOwnershipScenario 是两种提交顺序共用的检查主体：
122	// 先由 first 提交 w1，确认只影响 first；再由另一人提交同号 w1，
123	// 确认仍正常生效且两人的归属互不干扰。
124	func runSharedWaiverOwnershipScenario(t *testing.T, s *Store, first string) {
125		t.Helper()
126		owners := map[string]sharedWaiverOwner{}
127		for _, o := range sharedWaiverOwners() {
128			owners[o.student] = o
129		}
130		second := "s2"
131		if first == "s2" {
132			second = "s1"
133		}
134		of, os2 := owners[first], owners[second]
135	
136		// 先提交的一份生效后，只能使申请人的要求满足。
137		wFirst, a, err := s.ApplyWaiver(first, "r1", "w1", of.basis)
138		if err != nil || a != ActionCreated || wFirst.Status != WaiverApproved {
139			t.Fatalf("%s 首次提交 w1 应正常生效，得到 %+v action=%v err=%v",
140				first, wFirst, a, err)
141		}
142		if wFirst.StudentID != first || wFirst.ReqID != "r1" || wFirst.Basis != of.basis {
143			t.Fatalf("%s 的 w1 应登记在本人名下、指向本人 r1 与本人依据，得到 %+v",
144				first, wFirst)
145		}
146		assertWaiverOwnerSatisfied(t, s, first, of)
147	
148		// 另一人的要求仍未满足、学分为零，免修历史中不能出现前一人的申请。
149		assertWaiverOwnerUnmet(t, s, second, os2)
150		if ws := s.Waivers(second); len(ws) != 0 {
151			t.Fatalf("%s 的免修历史不能出现 %s 的申请，得到 %+v", second, first, ws)
152		}
153	
154		// 另一人随后提交自己的同号申请：不能被当作重复提交、编号冲突，
155		// 也不能误判为该要求已经免修，必须作为本人的新申请正常生效。
156		wSecond, a, err := s.ApplyWaiver(second, "r1", "w1", os2.basis)
157		if err != nil || a != ActionCreated || wSecond.Status != WaiverApproved {
158			t.Fatalf("%s 提交同号 w1 应正常生效而非被判重复/冲突，得到 %+v action=%v err=%v",
159				second, wSecond, a, err)
160		}
161		if wFirst == wSecond {
162			t.Fatal("两名学生的同号免修应是各自独立的记录，不应返回同一条")
163		}
164	
165		// 此时两人的核对结果分别为各自课程学分，来源均指向本人名下的 w1，
166		// 免修历史各保留本人的依据。
167		assertWaiverOwnerSatisfied(t, s, first, of)
168		assertWaiverOwnerSatisfied(t, s, second, os2)
169	
170		// 要求和免修编号相同，仍应能从各自的学生记录中分清对应的课程与依据。
171		if s.Requirement(first, "r1") == s.Requirement(second, "r1") {
172			t.Fatal("两名学生的同号要求应是各自独立的记录")
173		}
174		if got := s.Requirement(first, "r1"); got.CourseID != of.course {
175			t.Fatalf("%s 的 r1 应指向 %s，得到 %s", first, of.course, got.CourseID)
176		}
177		if got := s.Requirement(second, "r1"); got.CourseID != os2.course {
178			t.Fatalf("%s 的 r1 应指向 %s，得到 %s", second, os2.course, got.CourseID)
179		}
180	}
181	
182	// TestSharedWaiverIDsOwnership 两名学生的要求编号与免修编号完全相同
183	// （r1/w1），s1 先提交：申请归属、有效状态、学分来源与免修历史必须各归各。
184	func TestSharedWaiverIDsOwnership(t *testing.T) {
185		s := NewStore()
186		owners := sharedWaiverOwners()
187		setupSharedWaivers(t, s, owners)
188		runSharedWaiverOwnershipScenario(t, s, "s1")
189	
190		// 保存并重新打开：同号记录的归属、来源与历史仍应能按学生分清。
191		path := filepath.Join(t.TempDir(), "records.json")
192		if err := s.Save(path); err != nil {
193			t.Fatalf("Save: %v", err)
194		}
195		loaded, existed, err := Load(path)
196		if err != nil || !existed {
197			t.Fatalf("Load: existed=%v err=%v", existed, err)
198		}
199		for _, o := range owners {
200			assertWaiverOwnerSatisfied(t, loaded, o.student, o)
201		}
202	}
203	
204	// TestSharedWaiverIDsOwnershipReversed 交换登记与提交顺序（s2 先登记、
205	// 先提交），归属结论必须一致，证明规则不依赖先登记或先处理哪名学生。
206	func TestSharedWaiverIDsOwnershipReversed(t *testing.T) {
207		s := NewStore()
208		owners := sharedWaiverOwners()
209		reverse := []sharedWaiverOwner{owners[1], owners[0]}
210		setupSharedWaivers(t, s, reverse)
211		runSharedWaiverOwnershipScenario(t, s, "s2")
212	}
213	
214	// TestSharedWaiverSameStudentRulesDoNotCross 在两名学生各有一份同号 w1
215	// 生效后，同一学生名下既有的幂等与冲突限制仍要成立，且任何拒绝都不能
216	// 改动另一人的同号记录。
217	func TestSharedWaiverSameStudentRulesDoNotCross(t *testing.T) {
218		s := NewStore()
219		owners := sharedWaiverOwners()
220		setupSharedWaivers(t, s, owners)
221	
222		s1, s2 := owners[0], owners[1]
223		w1s1, a, err := s.ApplyWaiver("s1", "r1", "w1", s1.basis)
224		if err != nil || a != ActionCreated || w1s1.Status != WaiverApproved {
225			t.Fatalf("s1 首次申请应生效，得到 %+v action=%v err=%v", w1s1, a, err)
226		}
227		w1s2, a, err := s.ApplyWaiver("s2", "r1", "w1", s2.basis)
228		if err != nil || a != ActionCreated || w1s2.Status != WaiverApproved {
229			t.Fatalf("s2 同号申请应生效，得到 %+v action=%v err=%v", w1s2, a, err)
230		}
231	
232		// 原编号、原要求、原依据再次提交：返回本人的原申请，历史条数和学分不增加。
233		for i := 0; i < 2; i++ {
234			got, a, err := s.ApplyWaiver("s1", "r1", "w1", s1.basis)
235			if err != nil || a != ActionExisted || got != w1s1 {
236				t.Fatalf("第 %d 次原样重复提交应返回 s1 的原申请，得到 %+v action=%v err=%v",
237					i+1, got, a, err)
238			}
239			if got.Status != WaiverApproved || got.Basis != s1.basis {
240				t.Fatalf("重复提交不应改变原申请，得到 %+v", got)
241			}
242		}
243		if n := len(s.Waivers("s1")); n != 1 {
244			t.Fatalf("原样重复提交不应新增申请，s1 历史应有 1 条，得到 %d", n)
245		}
246		assertWaiverOwnerSatisfied(t, s, "s1", s1)
247	
248		// 在原 w1 下改换依据：按内容冲突拒绝，不新增申请，原依据与有效状态保留。
249		if _, _, err := s.ApplyWaiver("s1", "r1", "w1", "改换后的依据"); err == nil {
250			t.Fatal("同一学生在原免修编号下改换依据应被拒绝")
251		} else if !strings.Contains(err.Error(), "w1") {
252			t.Fatalf("冲突拒绝应点名原免修编号 w1，得到 %v", err)
253		}
254		if n := len(s.Waivers("s1")); n != 1 {
255			t.Fatalf("内容冲突不应新增申请，s1 历史应仍为 1 条，得到 %d", n)
256		}
257		if got := s.Waiver("s1", "w1"); got != w1s1 || got.Status != WaiverApproved ||
258			got.Basis != s1.basis || got.ReqID != "r1" {
259			t.Fatalf("冲突拒绝后 s1 的原 w1 应保持有效且依据不变，得到 %+v", got)
260		}
261		if rep := s.CheckStudent("s1"); rep.TotalCredits != 4 || len(rep.RejectedWaivers) != 0 {
262			t.Fatalf("冲突拒绝不应改变 s1 的学分或增加拒绝历史，得到学分=%d 拒绝=%d",
263				rep.TotalCredits, len(rep.RejectedWaivers))
264		}
265		// 不能改动另一人的同号记录。
266		if got := s.Waiver("s2", "w1"); got != w1s2 || got.Status != WaiverApproved ||
267			got.Basis != s2.basis {
268			t.Fatalf("s1 的冲突拒绝不应影响 s2 的 w1，得到 %+v", got)
269		}
270		assertWaiverOwnerSatisfied(t, s, "s2", s2)
271	
272		// 改用新免修编号 w2 再次取代已经免修的 r1：应被拒绝，并在提交者历史中
273		// 留下一条独立的拒绝记录（与 w1 并存，编号、目标、依据各不相同）。
274		w2, a, err := s.ApplyWaiver("s1", "r1", "w2", "再次申请的新依据")
275		if err != nil || a != ActionCreated || w2.Status != WaiverRejected {
276			t.Fatalf("新编号取代已有免修应新建被拒绝记录，得到 %+v action=%v err=%v",
277				w2, a, err)
278		}
279		if w2.ID != "w2" || w2.ReqID != "r1" || w2.Basis != "再次申请的新依据" ||
280			w2.Reason == "" || !strings.Contains(w2.Reason, "w1") {
281			t.Fatalf("拒绝记录应保留编号 w2、目标 r1、新依据，并指明已有有效免修 w1，得到 %+v", w2)
282		}
283		if ws := s.Waivers("s1"); len(ws) != 2 || ws[0] != w1s1 || ws[1] != w2 {
284			t.Fatalf("s1 历史应为 [w1 有效, w2 已拒绝] 两条独立记录，得到 %+v", ws)
285		}
286	
287		// 该学生的核对结果必须列出这次申请的编号、目标要求、依据，以及该要求
288		// 已有哪份有效免修的具体原因，不能只显示一个没有对应申请的失败提示。
289		rep := s.CheckStudent("s1")
290		if len(rep.RejectedWaivers) != 1 {
291			t.Fatalf("核对应列出 1 条被拒绝的免修申请，得到 %d", len(rep.RejectedWaivers))
292		}
293		rj := rep.RejectedWaivers[0]
294		if rj.Waiver != w2 || rj.Waiver.ID != "w2" || rj.Waiver.ReqID != "r1" ||
295			rj.Waiver.Basis != "再次申请的新依据" || !strings.Contains(rj.Reason, "w1") {
296			t.Fatalf("核对中的拒绝记录应对应 w2 申请并点名已有有效免修 w1，得到 %+v", rj)
297		}
298		out := rep.String()
299		for _, want := range []string{
300			"免修 w2（要求 r1，依据 \"再次申请的新依据\"）",
301			"该要求已有有效免修 w1",
302		} {
303			if !strings.Contains(out, want) {
304				t.Fatalf("核对文本应包含 %q，out=%q", want, out)
305			}
306		}
307	
308		// 原有效申请继续作为学分来源，课程学分仍只计一次，要求仍为已满足。
309		if rep.TotalCredits != 4 {
310			t.Fatalf("拒绝重复取代后仍应只计一次 4 学分，得到 %d", rep.TotalCredits)
311		}
312		if len(rep.Unmet) != 0 {
313			t.Fatalf("r1 应仍为已满足，未满足=%v", rep.Unmet)
314		}
315		st := rep.Requirements[0]
316		if !st.Satisfied || st.Source != "waiver" || st.WaiverID != "w1" {
317			t.Fatalf("学分来源应仍是原有效免修 w1，得到 %+v", st)
318		}
319		if got := s.Waiver("s1", "w1"); got.Status != WaiverApproved || got.Basis != s1.basis {
320			t.Fatalf("原 w1 应继续有效且依据不变，得到 %+v", got)
321		}
322		// 被拒绝的 w2 原样重复提交同样不新增、不生效。
323		if got, a, err := s.ApplyWaiver("s1", "r1", "w2", "再次申请的新依据"); err != nil ||
324			a != ActionExisted || got != w2 || got.Status != WaiverRejected {
325			t.Fatalf("w2 重复提交应返回原拒绝记录，得到 %+v action=%v err=%v", got, a, err)
326		}
327		if n := len(s.Waivers("s1")); n != 2 {
328			t.Fatalf("w2 重复提交不应新增记录，s1 历史应仍为 2 条，得到 %d", n)
329		}
330	
331		// 另一人的免修历史、有效申请和核对结果始终保持原样。
332		if ws := s.Waivers("s2"); len(ws) != 1 || ws[0] != w1s2 {
333			t.Fatalf("s2 的免修历史应始终只有本人的 w1，得到 %+v", ws)
334		}
335		assertWaiverOwnerSatisfied(t, s, "s2", s2)
336	}
337

