39			t.Fatalf("登记要求失败 out=%q", out)
40		}
41		if _, _, code := runCLI(t, file, "req", "s1", "r2", "c2"); code != 0 {
42			t.Fatal("登记要求失败")
43		}
44	
45		// 同一学生重复要求被拒绝。
46		if _, errText, code := runCLI(t, file, "req", "s1", "r3", "c1"); code == 0 {
47			t.Fatalf("重复课程要求应被拒绝，err=%q", errText)
48		}
49	
50		// 修读：同学期两次，不同编号。
51		if _, _, code := runCLI(t, file, "enroll", "s1", "r1", "2024春", "e1"); code != 0 {
52			t.Fatal("选课 e1 失败")
53		}
54		if _, _, code := runCLI(t, file, "enroll", "s1", "r1", "2024春", "e2"); code != 0 {
55			t.Fatal("选课 e2 失败")
56		}
57		// e1 未通过，e2 通过。
