67		}
68	
69		// r2 用免修满足。
70		if out, _, code := runCLI(t, file, "waiver", "s1", "r2", "w1", "竞赛获奖"); code != 0 ||
71			!strings.Contains(out, "有效") {
72			t.Fatalf("免修应有效 code=%d out=%q", code, out)
73		}
