85		}
86		if !strings.Contains(out, "有效免修 w1") {
87			t.Fatalf("应以免修 w1 说明 r2 来源，out=%q", out)
88		}
89		if strings.Contains(out, "未满足要求：[") {
90			t.Fatalf("不应有未满足要求，out=%q", out)
